-- Read-only catalog snapshot; no customer row content or mutating RPCs.
SELECT jsonb_build_object(
 'identity',jsonb_build_object('database',current_database(),'role',current_user,'version',current_setting('server_version'),'at',clock_timestamp()),
 'tables',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'acl',c.relacl,
  'privileges',(SELECT jsonb_agg(jsonb_build_object('role',r,'select',has_table_privilege(r,c.oid,'SELECT'),'insert',has_table_privilege(r,c.oid,'INSERT'),'update',has_table_privilege(r,c.oid,'UPDATE'),'delete',has_table_privilege(r,c.oid,'DELETE'))) FROM unnest(ARRAY['anon','authenticated','service_role']) r))) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('businesses','odin_inbox','odin_tasks','odin_conversations','odin_outbox')),
 'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'column',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notnull',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid)) ORDER BY c.relname,a.attnum) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relname IN ('businesses','odin_inbox','odin_tasks','odin_conversations','odin_outbox') AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',p.conname,'valid',p.convalidated,'definition',pg_get_constraintdef(p.oid)) ORDER BY c.relname,p.conname) FROM pg_constraint p JOIN pg_class c ON c.oid=p.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('businesses','odin_inbox','odin_tasks','odin_conversations','odin_outbox')),
 'indexes',(SELECT jsonb_agg(jsonb_build_object('table',t.relname,'name',c.relname,'valid',i.indisvalid,'ready',i.indisready,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY t.relname,c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_class t ON t.oid=i.indrelid JOIN pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relname IN ('businesses','odin_inbox','odin_tasks','odin_conversations','odin_outbox')),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p)), '[]'::jsonb) FROM pg_policies p WHERE schemaname='public' AND tablename LIKE 'odin_%'),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid)) ORDER BY c.relname,t.tgname) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname LIKE 'odin_%' AND NOT t.tgisinternal),
 'functions',(SELECT jsonb_agg(jsonb_build_object('name',p.proname,'signature',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'body',p.prosrc,'acl',p.proacl,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_role',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname LIKE 'odin_%'),
 'booking',(SELECT jsonb_agg(x ORDER BY x::text) FROM (
  SELECT jsonb_build_object('kind','table','name',c.relname,'rls',c.relrowsecurity,'acl',c.relacl,'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped)) x FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('appointments','appointments_leads','booking_result_outbox','booking_slot_reservations')
  UNION ALL SELECT jsonb_build_object('kind','function','name',p.proname,'definition',pg_get_functiondef(p.oid),'acl',p.proacl) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f' AND p.proname LIKE '%booking%'
  UNION ALL SELECT jsonb_build_object('kind','constraint','name',conname,'table',conrelid::regclass::text,'definition',pg_get_constraintdef(oid)) FROM pg_constraint WHERE conrelid IN ('public.appointments'::regclass,'public.appointments_leads'::regclass,'public.booking_result_outbox'::regclass,'public.booking_slot_reservations'::regclass)
  UNION ALL SELECT jsonb_build_object('kind','index','name',indexname,'table',tablename,'definition',indexdef) FROM pg_indexes WHERE schemaname='public' AND tablename IN ('appointments','appointments_leads','booking_result_outbox','booking_slot_reservations')
  UNION ALL SELECT jsonb_build_object('kind','policy','value',to_jsonb(p)) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('appointments','appointments_leads','booking_result_outbox','booking_slot_reservations')
 ) s),
 'counts',jsonb_build_object('conversations',(SELECT count(*) FROM public.odin_conversations),'inbox',(SELECT count(*) FROM public.odin_inbox),'tasks',(SELECT count(*) FROM public.odin_tasks),'outbox',(SELECT count(*) FROM public.odin_outbox)),
 'activity',(SELECT coalesce(jsonb_agg(jsonb_build_object('pid',pid,'application',application_name,'state',state,'xact_age_seconds',extract(epoch from clock_timestamp()-xact_start),'wait_type',wait_event_type,'wait_event',wait_event,'blockers',pg_blocking_pids(pid))),'[]'::jsonb) FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND (state<>'idle' OR cardinality(pg_blocking_pids(pid))>0)),
 'p2_locks',(SELECT coalesce(jsonb_agg(jsonb_build_object('relation',c.relname,'mode',l.mode,'granted',l.granted,'pid',l.pid)),'[]'::jsonb) FROM pg_locks l JOIN pg_class c ON c.oid=l.relation JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('odin_conversations','odin_inbox','odin_tasks','odin_outbox')),
 'cron',to_regclass('cron.job'), 'net_queue',to_regclass('net.http_request_queue')
) AS snapshot;
